import sys, json

def brief(s, n=220):
    s = s.replace("\n", " \\n ")
    return s[:n] + ("…" if len(s) > n else "")

for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    try:
        d = json.loads(line)
    except Exception as e:
        print("PARSE_ERROR", e)
        continue
    ts = d.get("timestamp", "")
    typ = d.get("type", "")
    if typ == "attachment":
        continue
    msg = d.get("message", {})
    role = msg.get("role", "")
    content = msg.get("content", "")
    if isinstance(content, str):
        print(f"{ts} [{typ}/{role}] TEXT: {brief(content)}")
    elif isinstance(content, list):
        for c in content:
            ctype = c.get("type", "")
            if ctype == "text":
                print(f"{ts} [{typ}/{role}] TEXT: {brief(c.get('text',''))}")
            elif ctype == "thinking":
                print(f"{ts} [{typ}/{role}] THINKING: {brief(c.get('thinking',''))}")
            elif ctype == "tool_use":
                print(f"{ts} [{typ}/{role}] TOOL_USE: {c.get('name')} input={brief(json.dumps(c.get('input',{})))}")
            elif ctype == "tool_result":
                cc = c.get("content", "")
                if isinstance(cc, list):
                    cc = " ".join(x.get("text","") if isinstance(x,dict) else str(x) for x in cc)
                print(f"{ts} [{typ}/{role}] TOOL_RESULT: err={c.get('is_error')} {brief(str(cc))}")
            else:
                print(f"{ts} [{typ}/{role}] OTHER({ctype})")
    usage = msg.get("usage")
    if usage:
        print(f"    usage: in={usage.get('input_tokens')} cache_read={usage.get('cache_read_input_tokens')} cache_creation={usage.get('cache_creation_input_tokens')} out={usage.get('output_tokens')}")

